const KEYBOARD_SHORTCUTS: Record<string, () => void> = {
  "ctrl+k": () => setShowPalette(true),
  "ctrl+l": () => clearOutput(),
  "ctrl+r": () => setHistorySearch(true),
  "ctrl+c": () => cancelCommand(),
};

useEffect(() => {
  const handler = (e: KeyboardEvent) => {
    const key = `${e.ctrlKey ? "ctrl+" : ""}${e.key.toLowerCase()}`;
    if (KEYBOARD_SHORTCUTS[key]) {
      e.preventDefault();
      KEYBOARD_SHORTCUTS[key]();
    }
  };
  window.addEventListener("keydown", handler);
  return () => window.removeEventListener("keydown", handler);
}, []);

import { WebSocketServer } from "ws";

const wss = new WebSocketServer({ noServer: true });

wss.on("connection", (ws) => {
  ws.on("message", (msg) => {
    const { scanId } = JSON.parse(msg.toString());
    subscribeToScan(scanId, (update) => {
      ws.send(JSON.stringify(update));
    });
  });
});
